//! Exceptions passed across contract calls.

use super::Exn;
use super::{LibraryExn, SyscallExn};
use crate::call::CallError;
use crate::sys::{SyscallErrorCode, SyscallNo};
use crate::xdr::*;
use core::convert::Infallible;
#[cfg(feature = "debugging")]
use core::error::Error;
#[cfg(feature = "debugging")]
use core::fmt::Display;
#[cfg(feature = "debugging")]
use core::fmt::Write;
use core::fmt::{self, Debug};
#[cfg(feature = "debugging")]
use thiserror::Error;

/// An exception generated by a contract or by SDK library code, and then
/// serialized for passing to [`contract_abort`][crate::contract_abort].
///
/// When a contract invocation wishes to abort, it may provide context data in
/// a byte-buffer passed to the [`contract_abort`][crate::contract_abort]
/// syscall. The type of this data must be known in order for the caller to
/// decode it.  Contract methods wrapped by the SDK use `CrossExn<E>`, where
/// `E` is particular to the contract and other exception types known to the
/// SDK may also be represented. Dynamically-typed values passed to `abort()`
/// are downcasted and wrapped in `CrossExn`.
///
#[derive(PartialEq, ReadXDR, WriteXDR)]
pub struct CrossExn<E = Infallible>
where
    E: Exn,
{
    exn: Inner<E>,

    #[cfg(feature = "debugging")]
    location: Option<LocationString>,

    #[cfg(feature = "debugging")]
    backtrace: Option<BacktraceString>,
}

#[cfg(feature = "debugging")]
type LocationString = heapless::String<200>;

#[cfg(feature = "debugging")]
type BacktraceString = heapless::String<500>;

impl<E> Debug for CrossExn<E>
where
    E: Exn,
{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        #[cfg(feature = "debugging")]
        display_error(&self.exn, f)?;

        #[cfg(not(feature = "debugging"))]
        Debug::fmt(&self.exn, f)?;

        #[cfg(feature = "debugging")]
        if let Some(loc) = self.location.as_ref() {
            write!(f, " at {}", loc)?;
        }

        #[cfg(feature = "debugging")]
        if let Some(bt) = self.backtrace.as_ref()
            && !bt.is_empty()
        {
            write!(f, "\nContext:\n{}", bt)?;
        }

        Ok(())
    }
}

#[cfg(feature = "debugging")]
fn display_error(err: &dyn Error, f: &mut fmt::Formatter) -> fmt::Result {
    fn more(err: &dyn Error, f: &mut fmt::Formatter, n: usize) -> fmt::Result {
        for _ in 0..n {
            write!(f, "  ")?;
        }
        if n > 0 {
            write!(f, "-> ")?;
        }
        writeln!(f, "{}", err)?;

        if let Some(err) = err.source() {
            more(err, f, n + 1)?;
        }

        Ok(())
    }

    more(err, f, 1)
}

// Delegate Display::fmt to &self.exn
#[cfg(feature = "debugging")]
impl<E> Display for CrossExn<E>
where
    E: Exn,
{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        Display::fmt(&self.exn, f)
    }
}

// Delegate Error::source to &self.exn
#[cfg(feature = "debugging")]
impl<E> Error for CrossExn<E>
where
    E: Exn + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        self.exn.source()
    }
}

impl<E> CrossExn<E>
where
    E: Exn,
{
    // An error resulting from a contract-call
    pub fn from_call_err<CE: Exn>(err: CallError<CE>) -> Self {
        let exn = Inner::Library(LibraryExn::Called(err.into_fault_string()));

        #[cfg(feature = "debugging")]
        {
            Self {
                exn,
                backtrace: None,
                location: None,
            }
        }

        #[cfg(not(feature = "debugging"))]
        Self { exn }
    }

    #[cfg(feature = "debugging")]
    pub fn location(&self) -> Option<&LocationString> {
        self.location.as_ref()
    }

    #[cfg(feature = "debugging")]
    pub fn backtrace(&self) -> Option<&BacktraceString> {
        self.backtrace.as_ref()
    }

    pub fn is_unknown(&self) -> bool {
        matches!(&self.exn, Inner::Unknown)
    }

    pub fn as_library_exn(&self) -> Option<&LibraryExn> {
        match &self.exn {
            Inner::Library(exn) => Some(exn),
            _ => None,
        }
    }

    pub fn as_syscall_exn(&self) -> Option<&SyscallExn> {
        self.as_library_exn().and_then(|e| e.as_syscall_exn())
    }

    pub fn as_contract_exn(&self) -> Option<&E> {
        match &self.exn {
            Inner::Contract(exn) => Some(exn),
            _ => None,
        }
    }

    pub fn is_syscall_exn(
        &self,
        call_no: SyscallNo,
        err_code: SyscallErrorCode,
    ) -> bool {
        self.as_library_exn()
            .and_then(|e| e.as_syscall_exn())
            .map(|e| e.is(call_no, err_code))
            .unwrap_or(false)
    }

    #[cfg(feature = "debugging")]
    #[track_caller]
    fn from_inner(exn: Inner<E>) -> Self {
        let location = Some(format(Location::caller()));
        let backtrace = Some(format(&::abort::Backtrace::capture()));

        Self {
            exn,
            location,
            backtrace,
        }
    }

    #[cfg(not(feature = "debugging"))]
    fn from_inner(exn: Inner<E>) -> Self {
        Self { exn }
    }
}

#[cfg(feature = "debugging")]
fn format<T, const N: usize>(v: &T) -> heapless::String<N>
where
    T: Display,
{
    let mut s = heapless::String::<N>::new();

    write!(&mut s, "{}", v).unwrap(); // XXX

    s
}

// Private structure
#[derive(Debug, PartialEq, ReadXDR, WriteXDR)]
#[cfg_attr(feature = "debugging", derive(Error))]
#[repr(i32)]
enum Inner<E = Infallible>
where
    E: Exn,
{
    #[cfg_attr(feature = "debugging", error(transparent))]
    Contract(E) = 0,

    #[cfg_attr(feature = "debugging", error(transparent))]
    Library(LibraryExn) = 1,

    #[cfg_attr(feature = "debugging", error("Unknown error"))]
    Unknown = 2,
}

#[cfg(feature = "debugging")]
use core::panic::Location;

#[cfg_attr(feature = "debugging", track_caller)]
pub fn contract_exn<E: Exn>(exn: E) -> CrossExn<E> {
    CrossExn::from_inner(Inner::Contract(exn))
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn library_exn<E: Into<LibraryExn>>(e: E) -> CrossExn<Infallible> {
    CrossExn::from_inner(Inner::Library(e.into()))
}
